CREATE TABLE remote_sources (id VARCHAR(36) PRIMARY KEY, library_id VARCHAR(36) NOT NULL, provider_type VARCHAR(16) NOT NULL, name VARCHAR(128) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, config JSON NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'READY', auto_sync_enabled BOOLEAN NOT NULL DEFAULT TRUE, auto_sync_interval_minutes INT NOT NULL DEFAULT 720, last_sync_at VARCHAR(40), last_successful_sync_at VARCHAR(40), next_sync_at VARCHAR(40), last_error TEXT, last_error_at VARCHAR(40), created_by VARCHAR(36) NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, INDEX idx_remote_sources_library(library_id, provider_type), INDEX idx_remote_sources_due(next_sync_at), CONSTRAINT chk_remote_provider CHECK (provider_type IN ('M3U_URL','M3U_FILE','GOOGLE_DRIVE')), FOREIGN KEY(library_id) REFERENCES libraries(id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE remote_source_secrets (source_id VARCHAR(36) PRIMARY KEY, secret_ref TEXT NOT NULL, updated_at VARCHAR(40) NOT NULL, FOREIGN KEY(source_id) REFERENCES remote_sources(id) ON DELETE CASCADE) ENGINE=InnoDB;
